    REFERENCE_TIME m_trRememberStampForPerf; // +0x118
    int           m_cFramesDropped;          // +0x120
    int           m_cFramesDrawn;            // +0x124
    LONGLONG      m_iTotAcc;                 // +0x128
    LONGLONG      m_iSumSqAcc;               // +0x130
