    LONGLONG      m_iSumSqFrameTime;         // +0x140
    LONGLONG      m_iSumFrameTime;           // +0x148
    int           m_trLate;                  // +0x150
    int           m_trFrame;                 // +0x154
    int           m_tStreamingStart;         // +0x158
    HRESULT ResetStreamingTimes();
};

HRESULT CBaseVideoRenderer::ResetStreamingTimes()
{
    m_trLastDraw = -1000;
    m_tStreamingStart = timeGetTime();
    m_trRenderAvg = 0;
    m_trFrameAvg = -1;
    m_trDuration = 0;
    m_trRenderLast = 0;
    m_trWaitAvg = 0;
    m_tRenderStart = 0;
    m_cFramesDrawn = 0;
    m_cFramesDropped = 0;
    m_iTotAcc = 0;
    m_iSumSqAcc = 0;
    m_iSumSqFrameTime = 0;
    m_trFrame = 0;
    m_trLate = 0;
    m_iSumFrameTime = 0;
    m_nNormal = 0;
    m_trEarliness = 0;
    m_trTarget = -300000;
    m_trThrottle = 0;
    m_trRememberStampForPerf = 0;
    return 0;   // NOERROR
}

